import { createRoot } from "react-dom/client";
import { useState } from "react";
// index.html의 root에 준비된 화면을 그려요.
function App() {
  const [draft, setDraft] = useState("");
  const [saved, setSaved] = useState("");
  // 제출 기본 이동을 막고 이번 화면의 상태에만 보관해요.
  function save(event) { event.preventDefault(); setSaved(draft); }
  return <main><h1>글 목록</h1><form onSubmit={save}><input aria-label="새 글" value={draft} onChange={event => setDraft(event.target.value)} /><button>저장</button></form><output>{JSON.stringify(saved)}</output></main>;
}
createRoot(document.getElementById("root")).render(<App />);

